    @Test fun upstreamRegressionGoldens() {
        for ((i, case) in cases.withIndex()) {
            val shaping = ArabicShaping(case.options)
            assertEquals(case.expected, shaping.shape(case.source), "fixture $i / ${case.options}")
            val source = ("##" + case.source + "!!").toCharArray()
            val saved = source.copyOf()
            val dest = CharArray(case.source.length * 2 + 8) { '#' }
            val length = shaping.shape(source, 2, case.source.length, dest, 3, dest.size - 3)
            assertEquals(case.expected, dest.concatToString(3, 3 + length), "buffer fixture $i")
            assertContentEquals(saved, source)
            assertEquals("###", dest.concatToString(0, 3))
            assertTrue(dest.drop(3 + length).all { it == '#' })
        }
    }
    @Test fun bufferFailuresAndSizingKeepSourceBehavior() {
        val shape = ArabicShaping(ArabicShaping.LETTERS_SHAPE)
        assertEquals(1, shape.shape("لا".toCharArray(), 0, 2, null, -999, 0))
        val unshape = ArabicShaping(ArabicShaping.LETTERS_UNSHAPE)
        assertEquals(2, unshape.shape("ﻻ".toCharArray(), 0, 1, null, 999, 0))
        val dest = charArrayOf('#')
        assertFailsWith<ArabicShapingException> { unshape.shape("ﻻ".toCharArray(), 0, 1, dest, 0, 1) }
        assertEquals('#', dest[0])
        assertFailsWith<ArabicShapingException> { shape.shape(null, 0, 0) }
        assertFailsWith<IllegalArgumentException> { shape.shape(null, 0, 0, null, 0, 0) }
        assertFailsWith<IllegalArgumentException> { ArabicShaping(0xa0) }
        assertEquals(0, shape.shape(charArrayOf(), 0, 0, null, Int.MIN_VALUE, 0))
    }
    @Test fun fixedLengthAliasingAndValueSemantics() {
        val options = ArabicShaping.LETTERS_SHAPE or ArabicShaping.LAMALEF_NEAR
        val shaping = ArabicShaping(options)
        val buffer = "##لا!!".toCharArray()
        shaping.shape(buffer, 2, 2)
        assertEquals("##ﻻ !!", buffer.concatToString())
        assertEquals(shaping, ArabicShaping(options))
        assertEquals(options, shaping.hashCode())
        assertNotEquals(shaping, ArabicShaping(ArabicShaping.LETTERS_UNSHAPE))
        assertFalse(shaping.equals("ArabicShaping"))
        assertTrue(shaping.toString().endsWith("[LamAlef spaces at near, logical, shape letters, no digit shaping, standard Arabic-Indic digits]"))
    }
